[2439] = { en = "The Platinum Discs", tier = 4,
  t = "De platina schijven",
  d = "Dit voorwerp is een ongelooflijke vondst. De oude Titans, of de Creators, zoals ze in deze schijven heten, zijn de verbinding met onze betoverde schepping, als de kennis die hierin is opgeslagen klopt! We moeten hier zoveel mogelijk onderzoekstijd in steken.$B$BEn jij, heldhaftige $c, brengt deze waardebon naar Dinita Stonemantle in de kluis. Je krijgt er iets voor wat volgens mij past bij zo'n enorme vondst!$B$BKom direct naar me terug als je klaar bent; er is nog veel meer te doen voor de Explorers' League!",
  o = "Breng je waardebon voor de beloning naar Dinita Stonemantle in de Vault of Ironforge.",
  p = "Welkom in de Vault of Ironforge, $N. Wat kan ik vandaag voor je doen?",
  c = "Ah ja, een waardebon van de Explorers' League... en een behoorlijk waardevolle, als ik dat mag zeggen.$B$BDe Explorers' League geeft me het recht om je als vergoeding zelf iets te laten kiezen, direct uit hun kluis. Je krijgt dit voorwerp, en als beloning mag je kiezen tussen vijf Superior Healing Potions of vijf Greater Mana Potions.",
  g = { {"platina", "platinum"}, {"schijven", "discs (schijf)"}, {"vondst", "find, discovery"}, {"schepping", "creation"}, {"opgeslagen", "stored (opslaan)"}, {"onderzoekstijd", "research time"}, {"heldhaftige", "heroic (heldhaftig)"}, {"waardebon", "voucher"}, {"kluis", "vault"}, {"behoorlijk", "quite, rather"}, {"waardevolle", "valuable (waardevol)"}, {"vergoeding", "compensation"} },
},

[3639] = { en = "Show Your Work", tier = 4,
  t = "Laat je werk zien",
  d = "Als je mentor wil ik voorbeelden van je werk zien. Je bent een bekwame ingenieur, daar twijfelt niemand aan, $N. Maar ik wil je werk onderzoeken, om te zien hoe je in de toekomst meer nadruk kunt leggen op goblintechnieken. Ik heb het volgende nodig: twintig Big Iron Bombs, twintig Solid Dynamite en vijf Explosive Sheep - en laat de beveiliging erop!$B$BLever deze spullen bij mij in, dan geef ik je je eigen Goblin Engineer Membership Card. Die heb je nodig om bij alle trainers in Goblin Engineering terecht te kunnen!",
  o = "Breng 20 Big Iron Bombs, 20 Solid Dynamite en 5 Explosive Sheep naar Nixx Sprocketspring in Gadgetzan.",
  p = "Zodra ik je zelfgemaakte engineeringvoorwerpen heb ontvangen om ze te beoordelen, geef ik je een echte Goblin Engineer Membership Card! Zolang de kaart geldig is, kun je onbeperkt terecht bij elke trainer in Goblin Engineering, overal ter wereld.",
  c = "Hier is je eerste Goblin Engineer Membership Card!$b$bDe contributie voor deze kaart is al veertien dagen vooruit betaald; alle kaarten verlopen na twee weken activiteit. Als dat gebeurt, betaal dan je volgende contributie aan een trainer in Goblin Engineering om een nieuwe kaart te krijgen. Zonder de kaart vervalt je lidmaatschap tijdelijk en heb je geen toegang tot nieuwe bouwtekeningen.$b$bDit heeft nooit invloed op wat je al weet: eens een goblin-ingenieur, altijd een goblin-ingenieur.",
  g = { {"mentor", "mentor"}, {"bekwame", "skilled (bekwaam)"}, {"twijfelt", "doubts (twijfelen)"}, {"nadruk", "emphasis"}, {"beveiliging", "safety catch, safeties"}, {"Lever", "hand in (inleveren: 'lever ... in')"}, {"beoordelen", "to review, to judge"}, {"geldig", "valid"}, {"onbeperkt", "unlimited"}, {"contributie", "membership dues"}, {"vooruit", "in advance"}, {"verlopen", "expire (verlopen)"}, {"vervalt", "lapses (vervallen)"}, {"tijdelijk", "temporarily"}, {"bouwtekeningen", "schematics (bouwtekening)"} },
},

[3640] = { en = "The Pledge of Secrecy", tier = 4,
  t = "De gelofte van geheimhouding",
  d = "Gnome Engineering draait om de theorie van engineering, gevormd om onze behoeften te dienen! Met onze bouwtekeningen kunnen we apparaten maken die de wereld om ons heen beheersen; dat stond in de handleiding die je hebt gelezen.$B$BIn de handleiding stond ook onze eeuwenoude eed van geheimhouding over onze bouwtekeningen. Als je eenmaal gnoom-ingenieur bent, ligt het vast. Dan heb je helemaal geen toegang meer tot Goblin Engineering.$B$BAls je nog steeds gnoom-ingenieur wilt worden, onderteken dan dit document, waarin je belooft je hele leven te zwijgen, en spreek me daarna nog een keer. Denk er goed over na, $N.",
  o = "Als je ermee instemt om Gnome Engineer te worden, klik dan met de rechtermuisknop op de Pledge of Secrecy en spreek nog een keer met Tinkmaster Overspark in Ironforge.",
  p = "Als je het document hebt ondertekend en klaar bent om het aan mij te geven, dan ligt het vast.$B$BDe geheimen die ik met je ga delen zijn zo groot dat het ondertekenen van de Pledge of Secrecy absoluut noodzakelijk is. Ik heb er zelf ook een ondertekend, net als mijn broeders en zusters, de gnoom-ingenieurs. Je komt in een heel voornaam gezelschap terecht, Engineer $N!",
  c = "Welkom aan boord, $N! Binnenkort heb je toegang tot de meest geavanceerde bouwtekeningen voor engineering van heel Azeroth.$B$BNu je je hebt verbonden aan het nastreven van deze kennis, is het tijd om je engineeringwerk met een gnoomrichting te bekijken. Daarna helpen we je een plan te maken om je talenten in Gnome Engineering zo goed mogelijk te benutten!",
  g = { {"gelofte", "pledge, vow"}, {"geheimhouding", "secrecy"}, {"draait om", "is about (draaien om)"}, {"behoeften", "needs (behoefte)"}, {"beheersen", "control (beheersen)"}, {"eeuwenoude", "age-old (eeuwenoud)"}, {"eed", "oath"}, {"ligt het vast", "that's that, it's settled (vastliggen)"}, {"onderteken", "sign (ondertekenen)"}, {"zwijgen", "to keep silent"}, {"instemt", "agree (instemmen)"}, {"noodzakelijk", "necessary, critical"}, {"voornaam", "distinguished, illustrious"}, {"gezelschap", "company, fold"}, {"geavanceerde", "advanced (geavanceerd)"}, {"nastreven", "pursuit, pursuing"}, {"benutten", "to make the most of, harness"} },
},

