[4181] = { en = "Goblin Engineering", tier = 4,
  t = "Goblin Engineering",
  d = "Engineering op expertniveau kent twee aparte richtingen: gnoom en goblin. Ik noem Goblin Engineering alleen omdat ik een eerlijke trainer ben. Ze maken graag dingen die ontploffen, en het kan ze zelden schelen wat er in de weg staat - zelfs zijzelf niet.$B$B$N, lees deze handleiding. Als je wilt leren hoe je jezelf opblaast, breng hem dan naar Nixx Sprocketspring in Gadgetzan. Onthoud: het lidmaatschap is voor altijd en daarna kun je niet meer bij de andere richting. Zorg dus dat je zeker weet dat je dit wilt, voordat je zijn opdracht afmaakt.",
  o = "Als je meer wilt leren over Goblin Engineering, breng dan het Manual of Engineering Disciplines naar Nixx Sprocketspring in Gadgetzan.",
  p = "Ik ruik nieuwe rekruten net zoals ik uitstekend explosiepoeder ruik - van een kilometer afstand. Ben je gekomen om te leren over de kunst van de explosie?",
  c = "Nou $N, je was verstandig om bij mij les te komen nemen! Elke sukkel kan expert worden in de basis van engineering - de gnomen en hun radioactieve thuis Gnomeregan zijn daar het bewijs van. Maar je hebt een sterke geest en een vaste hand nodig (nadruk op VAST) om de richting Goblin Engineering te beheersen.$B$BHoud je oren open, $N, dan leer je misschien iets.",
  g = { {"expertniveau", "expert level"}, {"richtingen", "disciplines, directions (richting)"}, {"handleiding", "manual"}, {"lidmaatschap", "membership"}, {"rekruten", "recruits (rekruut)"}, {"explosiepoeder", "blasting powder"}, {"verstandig", "wise, sensible"}, {"sukkel", "fool, schlep"}, {"radioactieve", "irradiated, radioactive (radioactief)"}, {"vaste hand", "steady hand"}, {"nadruk", "emphasis"}, {"beheersen", "to master, to control"}, {"opblaast", "blow up (opblazen)"} },
},

[3201] = { en = "At Last!", tier = 4,
  t = "Eindelijk!",
  d = "Ik kan niet geloven dat Pebblebitty twijfelde of de hoorn echt was. Tussen ons gezegd: ik denk dat ze gewoon jaloers is. Ik weet dat ze dat beest heel graag zelf wilde doden, vanwege dat 'incident' en zo.$B$BDus je hebt een bewijs van je daad nodig? Na de bijdrage die je net aan het museum hebt geleverd, is dat geen probleem.$B$B<Curator Thorius begint een groot document in te vullen.>$B$BAlsjeblieft! Dat kun je terugbrengen naar Pebblebitty.",
  o = "Breng de Proof of Deed terug naar Mountaineer Pebblebitty.",
  p = "Ik geloof het niet.",
  c = "Ik weet niet hoe iemand die zo zwak is als jij Margol heeft verslagen, maar afspraak is afspraak. Hier is de sleutel.$B$BAls je hierna iets overkomt, is het je eigen schuld.",
  g = { {"twijfelde", "doubted (twijfelen)"}, {"Tussen ons gezegd", "between you and me"}, {"jaloers", "jealous"}, {"beest", "beast"}, {"bewijs", "proof"}, {"daad", "deed"}, {"bijdrage", "contribution"}, {"geleverd", "made, delivered (leveren)"}, {"verslagen", "defeated, overcame (verslaan)"}, {"afspraak is afspraak", "a deal is a deal"}, {"overkomt", "happens to (overkomen)"}, {"schuld", "fault"} },
},

[2946] = { en = "Seeing What Happens", tier = 4,
  t = "Kijken wat er gebeurt",
  d = "We willen dat je de miniatuurschijven die je hebt gevonden naar de verzegelde poorten van Uldum brengt. We... we weten niet zeker wat er gebeurt als je dat doet.$B$BDat klinkt riskant, zeker, dat geven we toe. Maar misschien gebeurt er ook helemaal niets. Misschien moet je de schijven ergens op gebruiken. Misschien gaan de deuren open als je de schijven bij je hebt. Sta open om alles te proberen, en wees klaar voor alles wat er kan gebeuren.$B$BAls je hebt ontdekt wat er gebeurt, kom dan terug naar Ironforge. We hebben veel te onderzoeken als je klaar bent!",
  o = "Breng de miniatuurschijven van platina naar de poorten van Uldum in Tanaris en zoek naar aanwijzingen over het verband tussen de twee.",
  p = "Deze sokkel, die er bekend uitziet, steekt uit het hete zand. Misschien heeft het een reden dat hij hier staat...",
  c = "Als je de sokkel aanraakt, beginnen de miniatuurschijven uit Uldaman in je rugzak te zoemen en te gloeien. Een bekend, tintelend gevoel gaat over je handen, en het beeld van nog een Stone Watcher komt tot leven voor de poorten van Uldum.$B$B\"Gegroet. Ik ben een bewaker van de toegang. Bij de schijven die voor toegang zijn gebruikt, ontbreken de juiste toegangsschijven: de Plates of Uldum. Voeg deze platen alsjeblieft toe aan de schijfstructuur en herhaal je toegangsprocedure. Dank je.\"",
  g = { {"miniatuurschijven", "miniature discs (miniatuurschijf)"}, {"verzegelde", "sealed (verzegeld)"}, {"poorten", "gates (poort)"}, {"riskant", "risky"}, {"geven", "give; with 'toe': admit (toegeven)"}, {"Sta open", "be open (openstaan)"}, {"aanwijzingen", "clues (aanwijzing)"}, {"verband", "connection"}, {"sokkel", "pedestal"}, {"zoemen", "to hum"}, {"gloeien", "to glow"}, {"tintelend", "tingling (tintelen)"}, {"bewaker", "guardian"}, {"ontbreken", "are missing (ontbreken)"}, {"toegangsprocedure", "access sequence"} },
},

[2963] = { en = "Portents of Uldum", tier = 4,
  t = "Voortekenen van Uldum",
  d = "Nogmaals gegroet, $n! Door je ontdekking in Uldaman is de Explorers' League helemaal opgewonden. De League probeert al een tijd de geheimen te ontrafelen van de kleine platina schijven die je hebt gevonden. Het is een gelukkig toeval dat je hier in de Hall bent, want nu kan ik je vertellen dat we misschien iets op het spoor zijn!$B$BHistorian Karnik heeft belangrijke aanwijzingen gevonden over de echte oorsprong van de Valley of the Watchers in de woestijn van Tanaris. Hij wil je zo snel mogelijk spreken!",
  o = "Spreek met Historian Karnik in de Hall of Explorers in Ironforge.",
  c = "Ik ben blij dat je nog steeds interesse hebt in ontdekkingen, $n! Met je natuurlijke talent en lef kunnen we geheimen openbreken waarvan we nooit dachten dat het mogelijk was!$B$BDe Discs of Norgannon in Uldaman waren een opslagplaats van enorm veel informatie; je mocht alleen bij de bovenste lagen, zogezegd, van de informatie die daar is opgeslagen. Volgens geruchten hadden de Creators nog meer opslagplaatsen, verspreid over Azeroth. Dat brengt ons nu bij Uldum...",
  g = { {"Voortekenen", "portents, omens (voorteken)"}, {"Nogmaals", "once again"}, {"opgewonden", "excited"}, {"ontrafelen", "to unravel, unlock"}, {"toeval", "coincidence, chance"}, {"op het spoor", "on the track of, on to"}, {"aanwijzingen", "clues (aanwijzing)"}, {"oorsprong", "origin"}, {"lef", "nerve, moxie"}, {"openbreken", "to crack open"}, {"opslagplaats", "repository, storehouse"}, {"lagen", "layers (laag)"}, {"zogezegd", "so to speak, as it were"}, {"geruchten", "rumours (gerucht)"}, {"verspreid", "spread out, scattered (verspreiden)"} },
},

[2964] = { en = "A Future Task", tier = 4,
  t = "Een taak voor later",
  d = "Tja, $n... we zitten hier voorlopig even vast. We weten wat we nodig hebben - de Plates of Uldum - maar we hebben geen idee waar ze kunnen zijn. We moeten er flink wat onderzoek naar doen om een goed plan van aanpak te bedenken. Ik heb een paar ideeën over waar we kunnen beginnen met zoeken. Ik heb goede hoop dat we je binnenkort vragen om op pad te gaan en ze terug te halen.$B$BDe High Explorer moet hierover worden ingelicht, $n. Hij wil je ongetwijfeld ook persoonlijk bedanken, omdat je de League weer hebt geholpen.",
  o = "Spreek met High Explorer Magellas in Ironforge.",
  c = "We zijn het dus allemaal eens: het beste plan van aanpak is om dit even stil te leggen, tot we beter weten in welke gebieden deze platen verborgen kunnen liggen. Jij hebt ons zo ver gebracht, $n, en ik hoop dat jij degene bent die weer het veld in gaat om Uldum voor ons allemaal te openen!$B$BIntussen geef ik je graag deze vergoeding. Die is voor alle kosten die je hebt gemaakt om ons te helpen, met nog iets extra's. Kom snel weer bij ons langs... Uldum roept!",
  g = { {"voorlopig", "for now, temporarily"}, {"zitten", "sit; with 'vast': are stuck (vastzitten)"}, {"flink wat", "quite a bit of"}, {"plan van aanpak", "plan of attack"}, {"op pad", "out, on the road"}, {"ingelicht", "informed (inlichten)"}, {"ongetwijfeld", "no doubt, undoubtedly"}, {"stil te leggen", "to put on hold (stilleggen)"}, {"verborgen", "hidden"}, {"degene", "the one"}, {"het veld in", "into the field"}, {"Intussen", "in the meantime"}, {"vergoeding", "compensation, honorarium"}, {"kosten", "expenses"} },
},

[2977] = { en = "Return to Ironforge", tier = 4,
  t = "Terug naar Ironforge",
  d = "Je gebruikt de sokkel opnieuw; de platina schijven zitten ineens weer in je rugzak.$B$BJe weet nu wat de Stone Watcher je heeft geleerd en je hebt de schijven terug. Het is tijd om terug te gaan naar Ironforge en de Explorers' League over je ontdekking te vertellen.",
  o = "Spreek met Historian Karnik in Ironforge.",
  p = "Welkom terug, $n. Kon je de schijven goed gebruiken, of was het uiteindelijk een vergeefse zoektocht?",
  c = "Je miste een paar schijven? Interessant genoeg lijken de Discs of Norgannon maar delen van de complete set te zijn - zoals sleutels aan een sleutelbos, zeg maar.$B$BAls we de Plates of Uldum kunnen vinden, kunnen we echt in het Uldum-complex zelf komen! Stel je voor dat je de plek kunt onderzoeken waar de Creators werkten, zonder een enorme schop mee te nemen!$B$BNiet dat er iets mis is met schoppen... of graven...",
  g = { {"sokkel", "pedestal"}, {"ineens", "suddenly"}, {"ontdekking", "discovery"}, {"uiteindelijk", "in the end"}, {"vergeefse zoektocht", "wild goose chase, futile search"}, {"Interessant genoeg", "interestingly enough"}, {"sleutelbos", "key ring"}, {"zeg maar", "if you will, so to speak"}, {"Stel je voor", "imagine (zich voorstellen)"}, {"schop", "shovel"}, {"graven", "digging, to dig"} },
},

[3790] = { en = "Assisting Arch Druid Staghelm", tier = 4,
  t = "Hulp voor Arch Druid Staghelm",
  d = "Neem me niet kwalijk, $c, maar ik wil graag even een moment van je tijd, als het kan.$B$BDe Cenarion Circle in Darnassus zoekt ervaren avonturiers zoals jij om hen te helpen bij een heel belangrijk onderzoeksproject. Ik ken de details niet, maar ik kan je wel vertellen dat niemand minder dan Arch Druid Fandral Staghelm dit onderzoek leidt.$B$BAlsjeblieft - als je interesse hebt, spreek dan rechtstreeks met hem in de Cenarion Enclave, in Darnassus zelf.",
  o = "Spreek met Arch Druid Fandral Staghelm in Darnassus.",
  c = "Zo, $c... omdat je hebt gehoord dat ik dit onderzoek zelf leid, ben je natuurlijk zo snel mogelijk gekomen.$B$BNu je hier bent, let dan goed op als ik je de details voor de eerste keer vertel; ik heb geen zin om mezelf te herhalen.",
  g = { {"Neem me niet kwalijk", "excuse me"}, {"ervaren", "seasoned, experienced"}, {"avonturiers", "adventurers (avonturier)"}, {"onderzoeksproject", "research project"}, {"niemand minder dan", "none other than"}, {"leidt", "leads (leiden)"}, {"rechtstreeks", "directly"}, {"herhalen", "to repeat"} },
},

[5090] = { en = "A Call to Arms: The Plaguelands!", tier = 4,
  t = "Te wapen: de Plaguelands!",
  d = "Hoor, hoor! Alle helden worden opgeroepen om naar deze woorden te luisteren!$B$BHet Kingdom of Stormwind roept op tot de wapens! Iedereen die gezond en sterk is, wordt gevraagd om de wapens op te nemen tegen de duistere dreiging van de Scourge in de noordelijke landen van de Eastern Kingdoms! Er gaan geruchten over nieuwe dreigingen die opkomen uit de ruïnes van de Plaguelands!$B$BHelden van het rijk - zoek Commander Ashlam Valorfist op. Hij heeft zijn basiskamp opgezet in Chillwind Camp, ten noorden van de Alterac Mountains!",
  o = "Zoek Commander Ashlam Valorfist op. Zijn basiskamp ligt in Chillwind Camp, ten noorden van de Alterac Mountains.",
  c = "Welkom in de Plaguelands, held. Dit is een van de gevaarlijkste grensgebieden van Azeroth, vooral met de dreiging van de Scourge, die ten noorden en noordoosten van ons boven ons hangt. Ik ben blij te horen dat de luide oproep tot plicht en dienst aan het grotere goed bij jou niet aan dovemansoren gericht was!$B$BAls je klaar bent om je handen vuil te maken, dan is er hier aan de rand van de Plaguelands genoeg te doen voor helden die willen en kunnen.",
  g = { {"Te wapen", "to arms"}, {"opgeroepen", "called upon (oproepen)"}, {"dreiging", "threat"}, {"duistere", "dark (duister)"}, {"geruchten", "rumours (gerucht)"}, {"opkomen", "rise up (opkomen)"}, {"ruïnes", "ruins (ruïne)"}, {"rijk", "realm, kingdom"}, {"basiskamp", "base camp"}, {"grensgebieden", "frontiers, border areas (grensgebied)"}, {"boven ons hangt", "looms over us (hangen)"}, {"plicht", "duty"}, {"het grotere goed", "the greater good"}, {"aan dovemansoren gericht", "fell on deaf ears"}, {"je handen vuil te maken", "to get your hands dirty"} },
},

[3448] = { en = "Passing the Burden", tier = 4,
  t = "De last doorgeven",
  d = "Ik heb onlangs de taak gekregen om Azshara te onderzoeken - een ooit prachtig gebied waar de elfen woonden. Dat was in de tijd dat ze nog magie gebruikten. Nu is het eerder gevaarlijk dan mooi, maar dat houdt ons niet tegen om elke steen om te draaien op zoek naar antwoorden over ons verleden.$B$BEen metgezel van mij, Tymor, bood aan om me te helpen het gebied te onderzoeken, want hij is erg geïnteresseerd in zulke dingen.$B$BHij heeft een kleine woning rechts van de Hall of Mysteries, hier in de stad.",
  o = "Spreek met Tymor in Ironforge.",
  c = "Ah, Karnik heeft je gestuurd, hè? Ik verwachtte al snel iets van hem te horen. Ik heb zulke prachtige dingen over Azshara ontdekt... Ik weet dat nachtelfen ongelooflijk lang leven, maar iedereen vergeet soms een paar van de wat... ongelukkige gebeurtenissen in zijn leven. Dat is niet als kritiek bedoeld, alleen als observatie.$B$BLang geleden bouwden de elfen steden vol kennis over magie en andere verloren kunsten. Omdat ik zulke dingen bestudeer, ben ik mijn onderzoek begonnen. Wat ik vond was heel spannend.",
  g = { {"last", "burden"}, {"doorgeven", "to pass on"}, {"onlangs", "recently"}, {"ooit", "once"}, {"eerder", "rather (eerder ... dan: rather ... than)"}, {"houdt", "holds; with 'tegen': stops (tegenhouden)"}, {"elke steen om te draaien", "to turn over every stone"}, {"metgezel", "companion"}, {"woning", "dwelling, small home"}, {"nachtelfen", "night elves (nachtelf)"}, {"ongelukkige", "unfortunate (ongelukkig)"}, {"gebeurtenissen", "events (gebeurtenis)"}, {"kritiek", "criticism"}, {"verloren kunsten", "lost arts"} },
},

[3449] = { en = "Arcane Runes", tier = 4,
  t = "Arcane runen",
  d = "Sommige elfen vereerden magie vroeger net zo veel als Elune zelf. Een aantal van hun machtigste magiërs maakte runen en tabletten met regels van de arcane magie en inzichten in wat ze hadden ontdekt. Die lieten ze op openbare plekken achter, zodat iedereen erover kon nadenken.$B$BIk wil heel graag afdrukken van deze runen uit de Ruins of Eldarath. Ik heb een set waarmee je de afdrukken kunt maken, maar je moet ze zelf vinden. Wees wel voorzichtig: de Explorer's League is niet de enige die interesse heeft in Eldarath.",
  o = "Maak met de Drawing Kit afdrukken van de Rune of Beth'Amara, de Rune of Jin'yael, de Rune of Markri en de Rune of Sael'hai. Ga daarna naar het kleine eiland bij het zuidelijke schiereiland van Azshara en geef Pilot Xiggs Fuselighter een signaal om ze op te halen.",
  p = "Kijk eens aan, fijn dat je het hier hebt gehaald, $N. Heb je de afdrukken voor Tymor?$B$BHoe gevaarlijk deze plek ook is, langs de kust is er niet veel gebeurd. Misschien komt dat door de naga die onder water zwemmen, maar dat is mijn probleem niet... ik patrouilleer in de lucht.",
  c = "Fijn om te zien dat je veilig en wel bent, $N. Ik hoop dat het niet te zwaar voor je was.$B$BIk breng deze meteen naar Tymor. Hij zal ze dolgraag bekijken.$B$BGooi het lichtkogelpistool maar weg... je hebt er waarschijnlijk toch niets meer aan, en ik heb al een nieuw.",
  g = { {"runen", "runes (rune)"}, {"vereerden", "revered, worshipped (vereren)"}, {"magiërs", "mages (magiër)"}, {"tabletten", "tablets (tablet)"}, {"inzichten", "insights (inzicht)"}, {"openbare", "public (openbaar)"}, {"afdrukken", "rubbings, prints (afdruk)"}, {"schiereiland", "peninsula"}, {"signaal", "signal"}, {"Kijk eens aan", "well, well, well"}, {"patrouilleer", "patrol (patrouilleren)"}, {"veilig en wel", "safe and sound"}, {"dolgraag", "very gladly, would love to"}, {"lichtkogelpistool", "flare gun"} },
},

[3450] = { en = "An Easy Pickup", tier = 4,
  t = "Een makkelijke ophaalklus",
  d = "Ik wil de afdrukken naar mijn toren laten brengen, maar jij hoeft niet helemaal daarheen te gaan. Ik laat ze gewoon door de lucht uit Azshara ophalen.$B$BXiggs Fuselighter is me nog een gunst of twee schuldig en hij is binnenkort in de buurt; hij heeft getekend om langs de kust te patrouilleren. Spreek met hem voordat je vertrekt. Hij kan je een lichtkogelpistool geven om hem een signaal te geven. Als je de afdrukken hebt, ga dan naar de plek die hij je noemt en geef ze aan hem, zodat hij ze veilig naar mijn toren kan brengen. Hij zou in de hangar in de Military Ward moeten zijn.",
  o = "Spreek met Xiggs Fuselighter in Ironforge.",
  c = "Wat kan ik voor je doen, $N? Ik heb het nu nogal druk, want ik maak mijn schip klaar voor een lange reis. Ik kwam alleen even langs bij een paar tankpiloten - ik heb wat wendigo-manen nodig om mijn cockpit mee te bekleden, en zij hebben er meestal een paar over.$B$BIk heb wel een minuutje als je het kort houdt... een van de jongens is net vertrokken naar Steelgrill's Depot om te kijken of de piloten daar manen voor me over hebben.",
  g = { {"ophaalklus", "pickup job"}, {"afdrukken", "rubbings, prints (afdruk)"}, {"toren", "tower"}, {"gunst", "favour"}, {"schuldig", "owing, in debt"}, {"getekend", "signed on (tekenen)"}, {"patrouilleren", "to patrol"}, {"lichtkogelpistool", "flare gun"}, {"tankpiloten", "tank pilots (tankpiloot)"}, {"manen", "manes (maan, manen)"}, {"bekleden", "to line, upholster"}, {"over", "left over, spare"} },
},

[3451] = { en = "Signal for Pickup", tier = 4,
  t = "Een signaal om op te halen",
  d = "Ah, dus Tymor heeft je gestuurd, hè? Ja, ik ben hem nog een gunst of twee schuldig. Wat zeg je? Wel, die kleine deugniet. Ja, daar kan ik hem wel mee helpen. Dus je hebt een lichtkogelpistool en een plek nodig... makkelijk genoeg.$B$BEr is een klein eiland bij het zuidelijke schiereiland van Azshara, waar we een landingsplaats hebben gemaakt. Neem dit lichtkogelpistool en gebruik het daar. Ik zie je signaal en kom langs om dit... wat het ook is dat hij wil, op te halen.",
  o = "Spreek met Xiggs Fuselighter en haal bij hem een Standard Issue Flare Gun in Ironforge.",
  c = "Hier is mijn standaard lichtkogelpistool. Wees geduldig als je het pistool hebt afgevuurd - er zitten maar een paar ladingen in, en het kan even duren voordat ik bij je ben, afhankelijk van hoe ver ik op zee ben. Kijk gewoon naar zee als je de lichtkogel hebt afgeschoten.",
  g = { {"signaal", "signal"}, {"gunst", "favour"}, {"schuldig", "owing, in debt"}, {"deugniet", "rascal, little devil"}, {"lichtkogelpistool", "flare gun"}, {"schiereiland", "peninsula"}, {"landingsplaats", "landing pad"}, {"geduldig", "patient"}, {"afgevuurd", "fired (afvuren)"}, {"ladingen", "charges (lading)"}, {"afhankelijk van", "depending on"}, {"lichtkogel", "flare"}, {"afgeschoten", "fired off (afschieten)"} },
},

[3461] = { en = "Return to Tymor", tier = 4,
  t = "Terug naar Tymor",
  d = "Tymor heeft me niets gegeven om je mee te betalen, dus ik raad je aan om het met hem te bespreken als je terug bent in Ironforge. Hij is vast nog in zijn huis in de Mystic Ward. Klop gewoon aan en zorg dat hij je goed betaalt. Deze plek is geen pretje... dat is zeker.$B$BMaar nogmaals bedankt dat je hem hebt geholpen, en succes.$B$BO, en ik heb de tekenset niet nodig. Waarom breng je hem niet terug naar Tymor als je naar hem toe gaat?",
  o = "Breng Tymor's Drawing Kit terug naar hem in Ironforge.",
  p = "Je bent terug! Uitstekend. Heb je mijn tekenset ook bij je?",
  c = "Geweldig! Ik ben zo blij dat te horen.$B$BIk heb echt zin om naar mijn toren te gaan en die afdrukken te bekijken. Ik ben zo jaloers op je... dat je naar een plek als Azshara bent gegaan. Dat is de droom van elke student van de arcane magie, zou ik denken.$B$BNou, we hebben het nooit over een beloning gehad, omdat je gewoon voor de Explorer's League werkte, maar je verdient wel iets.",
  g = { {"raad", "advise (aanraden: 'raad ... aan')"}, {"bespreken", "to discuss, take up"}, {"Klop", "knock (aankloppen: 'klop ... aan')"}, {"geen pretje", "no picnic, no fun"}, {"nogmaals", "once again"}, {"tekenset", "drawing kit"}, {"Uitstekend", "excellent"}, {"afdrukken", "rubbings, prints (afdruk)"}, {"jaloers", "jealous, envious"}, {"beloning", "reward"}, {"verdient", "deserve (verdienen)"} },
},

[3483] = { en = "Signal for Pickup", tier = 4,
  t = "Een signaal om op te halen",
  c = "Ah, nog een lichtkogelpistool, hè? Dat kan ik wel regelen.$B$BEn vergeet het niet: de zuidpunt van Azshara. Het is een klein eilandje dat is omgebouwd tot landingsplaats. Je kunt het niet missen als je op de goede plek bent.",
  g = { {"signaal", "signal"}, {"lichtkogelpistool", "flare gun"}, {"regelen", "to arrange, sort out"}, {"zuidpunt", "southern tip"}, {"eilandje", "little island"}, {"omgebouwd", "converted (ombouwen)"}, {"landingsplaats", "landing pad"}, {"missen", "to miss"} },
},

[4512] = { en = "A Little Slime Goes a Long Way", tier = 4,
  t = "Een beetje slijm helpt al veel",
  d = "Maar wat ik het meest heb bestudeerd, is slijm. Ik weet dat het vreemd klinkt, maar ze zijn overal!$B$BNiet zo lang geleden heb ik een vrouw in Menethil geholpen haar tas te vinden - die was opgegeten door slijmwezens. Ik heb leden van de Royal Apothecary Society uit Undercity monsters van het spul zien verzamelen. Ik wil weten waarom! Waar komt het vandaan?$B$BIk heb gehoord dat er meer zijn in Felwood. Ik heb monsters nodig van de slijmwezens daar, zodat ik mijn onderzoek verder kan brengen. Ik geef je potten; daarmee neem je een monster van de dode wezens.",
  o = "Breng 6 Filled Cursed Ooze Jars en 6 Filled Tainted Ooze Jars naar Laris Geardawdle in Ironforge.",
  p = "Sommige van mijn experimenten zijn fascinerend. Ik denk dat ik met nog wat werk kan ontdekken wat de aard van deze wezens is en welke rol ze speelden bij het ontstaan van het leven op Azeroth... als ze daar al iets mee te maken hebben.$B$BEen van mijn grootste theorieën, die niet erg populair is, is het idee dat slijmwezens en slijmbeesten verbonden zijn met de schepping van deze planeet... bijna alsof ze er een afscheiding van zijn.$B$BMaar ik kan het niet bewijzen of weerleggen tot ik meer monsters heb.",
  c = "Geweldige resultaten, $N! Je bent dicht genoeg bij die besmette dingen gekomen om een monster te nemen, en je ziet er niet slechter uit! Dank je. O, deze monsters zijn perfect. Ik kan niet wachten om ze te gaan testen.$B$BAls ik gelijk heb, kan ik een van de grootste wetenschappers van de Explorers' League worden!$B$BDat zal alle dwergen bewijzen dat het geen fout was om ons gnomen na het incident in Gnomeregan in Ironforge toe te laten.",
  g = { {"slijm", "slime, ooze"}, {"bestudeerd", "studied (bestuderen)"}, {"slijmwezens", "oozes (slijmwezen)"}, {"monsters", "samples (monster)"}, {"spul", "stuff"}, {"potten", "jars (pot)"}, {"fascinerend", "fascinating"}, {"aard", "nature"}, {"ontstaan", "development, origin"}, {"slijmbeesten", "slimes (slijmbeest)"}, {"schepping", "creation"}, {"afscheiding", "secretion"}, {"weerleggen", "to disprove"}, {"besmette", "corrupted, tainted (besmet)"}, {"toe te laten", "to admit, allow in (toelaten)"} },
},

})

